CREATE TABLE public.vibz_posts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE, media_path text NOT NULL UNIQUE, media_type text NOT NULL DEFAULT 'video/mp4', duration_seconds numeric(6,2) NOT NULL CHECK (duration_seconds > 0 AND duration_seconds < 120), caption text NOT NULL DEFAULT '' CHECK (length(caption) <= 500), status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','published','flagged','quarantined','deleted')), categories text[] NOT NULL DEFAULT '{}', confidence numeric(4,3), review_notes text, created_at timestamptz NOT NULL DEFAULT now(), reviewed_at timestamptz, deleted_at timestamptz, likes_count int NOT NULL DEFAULT 0, comments_count int NOT NULL DEFAULT 0, shares_count int NOT NULL DEFAULT 0, CONSTRAINT vibz_media_owner CHECK (split_part(media_path,'/',1) = creator_id::text));
GRANT SELECT, INSERT, DELETE ON public.vibz_posts TO authenticated; GRANT ALL ON public.vibz_posts TO service_role;
ALTER TABLE public.vibz_posts ENABLE ROW LEVEL SECURITY;
CREATE POLICY vibz_read ON public.vibz_posts FOR SELECT TO authenticated USING (status = 'published' OR creator_id = auth.uid() OR public.is_admin_user());
CREATE POLICY vibz_create ON public.vibz_posts FOR INSERT TO authenticated WITH CHECK (creator_id = auth.uid() AND status = 'pending' AND likes_count = 0 AND comments_count = 0 AND shares_count = 0 AND length(media_path) < 240 AND media_path ~ ('^' || auth.uid()::text || '/[a-zA-Z0-9-]+[.]mp4$') AND EXISTS (SELECT 1 FROM public.user_profiles p WHERE p.id = auth.uid() AND p.account_status = 'active' AND NOT p.is_suspended));
CREATE POLICY vibz_owner_delete ON public.vibz_posts FOR DELETE TO authenticated USING (creator_id = auth.uid() AND status <> 'quarantined');
CREATE INDEX vibz_feed_idx ON public.vibz_posts (created_at DESC) WHERE status = 'published'; CREATE INDEX vibz_creator_idx ON public.vibz_posts (creator_id, created_at DESC);
CREATE TABLE public.vibein (follower_id uuid NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE, creator_id uuid NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(follower_id,creator_id), CHECK (follower_id <> creator_id));
GRANT SELECT, INSERT, DELETE ON public.vibein TO authenticated; GRANT ALL ON public.vibein TO service_role;
ALTER TABLE public.vibein ENABLE ROW LEVEL SECURITY;
CREATE POLICY vibein_read ON public.vibein FOR SELECT TO authenticated USING (follower_id = auth.uid() OR creator_id = auth.uid()); CREATE POLICY vibein_add ON public.vibein FOR INSERT TO authenticated WITH CHECK (follower_id = auth.uid() AND EXISTS (SELECT 1 FROM public.user_profiles p WHERE p.id = creator_id AND p.account_status = 'active' AND NOT p.is_suspended)); CREATE POLICY vibein_remove ON public.vibein FOR DELETE TO authenticated USING (follower_id = auth.uid()); CREATE INDEX vibein_creator_idx ON public.vibein(creator_id);
CREATE TABLE public.vibz_likes (post_id uuid NOT NULL REFERENCES public.vibz_posts(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(post_id,user_id));
GRANT SELECT, INSERT, DELETE ON public.vibz_likes TO authenticated; GRANT ALL ON public.vibz_likes TO service_role; ALTER TABLE public.vibz_likes ENABLE ROW LEVEL SECURITY;
CREATE POLICY vibz_likes_read ON public.vibz_likes FOR SELECT TO authenticated USING (user_id = auth.uid() OR EXISTS (SELECT 1 FROM public.vibz_posts p WHERE p.id = post_id AND (p.status = 'published' OR p.creator_id = auth.uid()))); CREATE POLICY vibz_likes_add ON public.vibz_likes FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.vibz_posts p WHERE p.id = post_id AND p.status = 'published')); CREATE POLICY vibz_likes_remove ON public.vibz_likes FOR DELETE TO authenticated USING (user_id = auth.uid());
CREATE TABLE public.vibz_comments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), post_id uuid NOT NULL REFERENCES public.vibz_posts(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE, body text NOT NULL CHECK (length(trim(body)) BETWEEN 1 AND 500), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, DELETE ON public.vibz_comments TO authenticated; GRANT ALL ON public.vibz_comments TO service_role; ALTER TABLE public.vibz_comments ENABLE ROW LEVEL SECURITY;
CREATE POLICY vibz_comments_read ON public.vibz_comments FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.vibz_posts p WHERE p.id = post_id AND (p.status = 'published' OR p.creator_id = auth.uid())) OR public.is_admin_user()); CREATE POLICY vibz_comments_add ON public.vibz_comments FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.vibz_posts p WHERE p.id = post_id AND p.status = 'published')); CREATE POLICY vibz_comments_remove ON public.vibz_comments FOR DELETE TO authenticated USING (user_id = auth.uid() OR public.is_admin_user()); CREATE INDEX vibz_comments_post_idx ON public.vibz_comments(post_id,created_at);
CREATE TABLE public.vibz_shares (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), post_id uuid NOT NULL REFERENCES public.vibz_posts(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.vibz_shares TO authenticated; GRANT ALL ON public.vibz_shares TO service_role; ALTER TABLE public.vibz_shares ENABLE ROW LEVEL SECURITY;
CREATE POLICY vibz_shares_read ON public.vibz_shares FOR SELECT TO authenticated USING (user_id = auth.uid()); CREATE POLICY vibz_shares_add ON public.vibz_shares FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.vibz_posts p WHERE p.id = post_id AND p.status = 'published'));
CREATE TABLE public.vibz_moderation (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), post_id uuid NOT NULL REFERENCES public.vibz_posts(id) ON DELETE CASCADE, actor_id uuid, action text NOT NULL, categories text[] NOT NULL DEFAULT '{}', confidence numeric(4,3), details text, created_at timestamptz NOT NULL DEFAULT now(), email_status text, UNIQUE(post_id,id));
GRANT SELECT ON public.vibz_moderation TO authenticated; GRANT ALL ON public.vibz_moderation TO service_role; ALTER TABLE public.vibz_moderation ENABLE ROW LEVEL SECURITY;
CREATE POLICY vibz_moderation_read ON public.vibz_moderation FOR SELECT TO authenticated USING (public.is_admin_user());
CREATE FUNCTION public.vibz_count_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF TG_OP = 'INSERT' THEN UPDATE public.vibz_posts SET likes_count = likes_count + CASE WHEN TG_TABLE_NAME = 'vibz_likes' THEN 1 ELSE 0 END, comments_count = comments_count + CASE WHEN TG_TABLE_NAME = 'vibz_comments' THEN 1 ELSE 0 END, shares_count = shares_count + CASE WHEN TG_TABLE_NAME = 'vibz_shares' THEN 1 ELSE 0 END WHERE id = NEW.post_id; RETURN NEW; ELSE UPDATE public.vibz_posts SET likes_count = greatest(0,likes_count - CASE WHEN TG_TABLE_NAME = 'vibz_likes' THEN 1 ELSE 0 END), comments_count = greatest(0,comments_count - CASE WHEN TG_TABLE_NAME = 'vibz_comments' THEN 1 ELSE 0 END) WHERE id = OLD.post_id; RETURN OLD; END IF; END $$;
CREATE TRIGGER vibz_like_count AFTER INSERT OR DELETE ON public.vibz_likes FOR EACH ROW EXECUTE FUNCTION public.vibz_count_change(); CREATE TRIGGER vibz_comment_count AFTER INSERT OR DELETE ON public.vibz_comments FOR EACH ROW EXECUTE FUNCTION public.vibz_count_change(); CREATE TRIGGER vibz_share_count AFTER INSERT ON public.vibz_shares FOR EACH ROW EXECUTE FUNCTION public.vibz_count_change();
CREATE FUNCTION public.vibz_feed(_cursor timestamptz DEFAULT NULL, _limit int DEFAULT 12) RETURNS TABLE(id uuid, creator_id uuid, media_path text, caption text, created_at timestamptz, likes_count int, comments_count int, shares_count int, creator_name text, creator_username text, creator_avatar text, creator_bio text, vibed_in boolean, liked boolean) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT p.id,p.creator_id,p.media_path,p.caption,p.created_at,p.likes_count,p.comments_count,p.shares_count,u.full_name,u.username,CASE WHEN public.can_view_profile_photo(u.id,auth.uid()) THEN u.avatar_url ELSE NULL END,u.bio,EXISTS(SELECT 1 FROM public.vibein v WHERE v.creator_id = p.creator_id AND v.follower_id = auth.uid()),EXISTS(SELECT 1 FROM public.vibz_likes l WHERE l.post_id = p.id AND l.user_id = auth.uid()) FROM public.vibz_posts p JOIN public.user_profiles u ON u.id=p.creator_id WHERE auth.uid() IS NOT NULL AND p.status='published' AND (_cursor IS NULL OR p.created_at < _cursor) AND u.account_status = 'active' AND NOT u.is_suspended ORDER BY (CASE WHEN EXISTS(SELECT 1 FROM public.vibein v WHERE v.creator_id=p.creator_id AND v.follower_id=auth.uid()) THEN 2 ELSE 0 END + CASE WHEN EXISTS(SELECT 1 FROM public.vibz_likes l JOIN public.vibz_posts liked ON liked.id=l.post_id WHERE l.user_id=auth.uid() AND liked.creator_id=p.creator_id) THEN 1 ELSE 0 END) DESC, (p.likes_count + p.comments_count * 2 + p.shares_count * 2)::numeric / greatest(1,extract(epoch FROM now()-p.created_at)/3600 + 2) DESC,p.created_at DESC LIMIT greatest(1,least(coalesce(_limit,12),30)) $$;
REVOKE ALL ON FUNCTION public.vibz_feed(timestamptz,int) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.vibz_feed(timestamptz,int) TO authenticated;
CREATE FUNCTION public.vibz_search(_q text) RETURNS TABLE(id uuid, full_name text, username text, avatar_url text, bio text, vibemates bigint, vibed_in boolean) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT u.id,u.full_name,u.username,CASE WHEN public.can_view_profile_photo(u.id,auth.uid()) THEN u.avatar_url ELSE NULL END,u.bio,(SELECT count(*) FROM public.vibein v WHERE v.creator_id=u.id),EXISTS(SELECT 1 FROM public.vibein v WHERE v.creator_id=u.id AND v.follower_id=auth.uid()) FROM public.user_profiles u WHERE auth.uid() IS NOT NULL AND length(trim(_q)) >= 2 AND u.account_status='active' AND NOT u.is_suspended AND (u.full_name ILIKE '%' || replace(replace(trim(_q),'%','\%'),'_','\_') || '%' OR u.username ILIKE '%' || replace(replace(trim(_q),'%','\%'),'_','\_') || '%') ORDER BY CASE WHEN lower(u.username)=lower(trim(_q)) THEN 0 ELSE 1 END,u.full_name LIMIT 20 $$;
REVOKE ALL ON FUNCTION public.vibz_search(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.vibz_search(text) TO authenticated;
CREATE FUNCTION public.vibz_profile(_id uuid) RETURNS TABLE(id uuid, full_name text, username text, avatar_url text, bio text, vibemates bigint, vibein_count bigint, total_likes bigint, total_comments bigint, total_shares bigint, vibed_in boolean) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT u.id,u.full_name,u.username,CASE WHEN public.can_view_profile_photo(u.id,auth.uid()) THEN u.avatar_url ELSE NULL END,u.bio,(SELECT count(*) FROM public.vibein v WHERE v.creator_id=u.id),(SELECT count(*) FROM public.vibein v WHERE v.follower_id=u.id),(SELECT coalesce(sum(p.likes_count),0) FROM public.vibz_posts p WHERE p.creator_id=u.id AND p.status='published'),(SELECT coalesce(sum(p.comments_count),0) FROM public.vibz_posts p WHERE p.creator_id=u.id AND p.status='published'),(SELECT coalesce(sum(p.shares_count),0) FROM public.vibz_posts p WHERE p.creator_id=u.id AND p.status='published'),EXISTS(SELECT 1 FROM public.vibein v WHERE v.creator_id=u.id AND v.follower_id=auth.uid()) FROM public.user_profiles u WHERE auth.uid() IS NOT NULL AND u.id=_id AND (u.account_status='active' AND NOT u.is_suspended OR u.id=auth.uid()) $$;
REVOKE ALL ON FUNCTION public.vibz_profile(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.vibz_profile(uuid) TO authenticated;
CREATE POLICY vibz_media_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id='vibz-media' AND owner_id=auth.uid()::text AND (storage.foldername(name))[1]=auth.uid()::text AND name ~ ('^' || auth.uid()::text || '/[a-zA-Z0-9-]+[.]mp4$'));
CREATE POLICY vibz_media_read ON storage.objects FOR SELECT TO authenticated USING (bucket_id='vibz-media' AND (owner_id=auth.uid()::text OR public.is_admin_user() OR EXISTS(SELECT 1 FROM public.vibz_posts p WHERE p.media_path=name AND p.status='published')));
CREATE POLICY vibz_media_delete ON storage.objects FOR DELETE TO authenticated USING (bucket_id='vibz-media' AND owner_id=auth.uid()::text AND (storage.foldername(name))[1]=auth.uid()::text AND NOT EXISTS(SELECT 1 FROM public.vibz_posts p WHERE p.media_path=name AND p.status='quarantined'));